<?php
require_once __DIR__ . '/../db.php'; admin_required();
$pdo=db();$message='';
$allowed=['new','contacted','confirmed','closed'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if($id>0&&in_array($status,$allowed,true)){$stmt=$pdo->prepare('UPDATE requests SET status=? WHERE id=?');$stmt->execute([$status,$id]);$message='Request status updated.';}}
$rows=$pdo->query('SELECT * FROM requests ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);
admin_header('Guest & partner requests');if($message):?><div class="admin-alert ok"><?=e($message)?></div><?php endif;?><p>Open a row to see the full message. Update status as you follow up.</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Received</th><th>Type</th><th>Name / property</th><th>Room / email</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="request-row" tabindex="0" role="button" aria-label="Open request details" data-request='<?=e(json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP))?>'><td><?=e($r['created_at'])?></td><td><?=e($r['request_type'])?></td><td><?=e($r['guest_name'])?><br><?=e($r['property_name'])?></td><td><?=e($r['room_name'])?><br><?=e($r['email'])?></td><td><span class="admin-status"><?=e($r['status'])?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">No requests have been submitted yet.</td></tr><?php endif;?></tbody></table></div><div class="modal" id="request-modal" hidden><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" type="button" aria-label="Close">×</button><h2 id="modal-title">Request details</h2><dl class="detail-grid" id="request-detail-grid"></dl><form class="admin-form" method="post" style="margin-top:20px;padding:0;border:0"><?=csrf_field()?><input type="hidden" name="id" id="status-id"><label>Status<input name="status" list="status-options" required><datalist id="status-options"><?php foreach($allowed as $status):?><option value="<?=e($status)?>"><?php endforeach;?></datalist></label><p><button class="admin-button" type="submit">Save status</button></p></form></section></div><script>
const modal=document.getElementById('request-modal'),detail=document.getElementById('request-detail-grid'),statusId=document.getElementById('status-id'),statusInput=modal.querySelector('[name=status]');
const labels={request_type:'Request type',created_at:'Received',status:'Status',guest_name:'Name',email:'Email',phone:'WhatsApp',preferred_reply:'Preferred reply',room_name:'Requested room',checkin_date:'Check-in',checkout_date:'Check-out',guests:'Guests',budget:'Budget per night',notes:'Message',property_name:'Property',property_role:'Role',property_location:'Location'};
function openRequest(row){const data=JSON.parse(row.dataset.request);detail.replaceChildren();for(const [key,label] of Object.entries(labels)){if(!data[key])continue;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=data[key];detail.append(dt,dd)}statusId.value=data.id;statusInput.value=data.status;modal.hidden=false;modal.querySelector('.modal-close').focus()}
document.querySelectorAll('.request-row').forEach(row=>{row.addEventListener('click',()=>openRequest(row));row.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openRequest(row)}})});modal.querySelector('.modal-close').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',event=>{if(event.target===modal)modal.hidden=true});document.addEventListener('keydown',event=>{if(event.key==='Escape')modal.hidden=true});
</script><?php admin_footer();
